class Solution:
    def oddString(self, words: List[str]) -> str:
        def diff(w):
            return tuple(ord(w[i+1]) - ord(w[i]) for i in range(len(w) - 1))
        cnt = Counter(diff(w) for w in words)
        for w in words:
            if cnt[diff(w)] == 1:
                return w

