class Solution {
public:
    vector<int> diff(const string& w) {
        vector<int> d;
        for (int i = 0; i + 1 < (int)w.size(); i++)
            d.push_back(w[i+1] - w[i]);
        return d;
    }
    string oddString(vector<string>& words) {
        map<vector<int>, int> cnt;
        for (auto& w : words) cnt[diff(w)]++;
        for (auto& w : words)
            if (cnt[diff(w)] == 1) return w;
        return "";
    }
};

