class Solution {
    private int[] diff(String w) {
        int[] d = new int[w.length() - 1];
        for (int i = 0; i + 1 < w.length(); i++) d[i] = w.charAt(i+1) - w.charAt(i);
        return d;
    }
    public String oddString(String[] words) {
        Map<String, Integer> cnt = new HashMap<>();
        for (String w : words) cnt.put(Arrays.toString(diff(w)), cnt.getOrDefault(Arrays.toString(diff(w)), 0) + 1);
        for (String w : words)
            if (cnt.get(Arrays.toString(diff(w))) == 1) return w;
        return "";
    }
}

