class Solution:
    def oddString(self, words: List[str]) -> str:
        def diff(w):
            return [ord(b) - ord(a) for a, b in zip(w, w[1:])]
        d0, d1 = diff(words[0]), diff(words[1])
        if d0 == d1:
            for w in words[2:]:
                if diff(w) != d0:
                    return w
        else:
            return words[0] if d0 != diff(words[2]) else words[1]

