class Solution {
    private int[] diff(String w) {
        int[] d = new int[w.length() - 1];
        for (int i = 0; i + 1 < w.length(); i++) d[i] = w.charAt(i+1) - w.charAt(i);
        return d;
    }
    private boolean eq(int[] a, int[] b) { return Arrays.equals(a, b); }
    public String oddString(String[] words) {
        int[] d0 = diff(words[0]), d1 = diff(words[1]), d2 = diff(words[2]);
        int[] common = eq(d0, d1) ? d0 : d2;
        for (String w : words)
            if (!eq(diff(w), common)) return w;
        return "";
    }
}

